      "definition": "Respondents selecting at least one tracked gaming brand or title in aided awareness.",
      "qualification_rule": "BRAND_AWARENESS_AIDED contains one or more options other than None of these.",
      "expected_path": "Continue through the applicable familiarity, usage, perception, emotional, loyalty, and monetisation path."
    },
    {
      "key": "non_aware",
      "definition": "Respondents who do not recognise any tracked gaming brand or title in aided awareness.",
      "qualification_rule": "BRAND_AWARENESS_AIDED selects None of these and no other option.",
      "expected_path": "Terminate immediately after SALIENCE."
    },
    {
      "key": "current_fortnite_player",
      "definition": "Brand-aware respondents who play Fortnite within the defined current-use window.",
      "qualification_rule": "FORTNITE_STATUS selects Current Fortnite player.",
      "expected_path": "Receive current-player engagement module, shared emotional and loyalty measures, and payer routing."
    },
    {
      "key": "lapsed_fortnite_player",
      "definition": "Respondents who previously played Fortnite but do not play within the defined current-use window.",
      "qualification_rule": "FORTNITE_STATUS selects Lapsed/former Fortnite player.",
      "expected_path": "Receive lapsed stopping, switching, churn, and return module, followed by shared emotional and loyalty measures."
    },
    {
      "key": "competitor_only_player",
      "definition": "Respondents who play tracked competitors but have never played Fortnite.",
      "qualification_rule": "FORTNITE_STATUS selects Competitor player who has never played Fortnite.",
      "expected_path": "Receive competitor conquest and Fortnite trial-barrier module, followed by shared emotional and loyalty measures where applicable."
    },
    {
      "key": "aware_non_player",
      "definition": "Brand-aware respondents without current, lapsed, or competitor-only Fortnite status.",
      "qualification_rule": "FORTNITE_STATUS selects Aware but not a current, lapsed, or competitor-only player.",
      "expected_path": "Skip lifecycle-specific modules and continue through shared brand, emotional, loyalty, and payer measures."
    },
    {
      "key": "payer",
      "definition": "Respondents who made an in-app purchase in the defined recent purchase window.",
      "qualification_rule": "PAYER_STATUS selects Yes, made an in-app purchase.",
      "expected_path": "Receive payer purchase behavior and value module."
    },
    {
      "key": "non_payer",
      "definition": "Respondents with no in-app purchase in the defined recent purchase window.",
      "qualification_rule": "PAYER_STATUS selects No purchase in the recent period.",
      "expected_path": "Receive spending-barrier and value module."
    }
  ],
  "questionnaire_sections": [
    {
      "key": "SALIENCE",
      "purpose": "Measure spontaneous and prompted brand awareness before any detailed brand evaluation, supporting the salience and funnel objectives.",
      "question_keys": [
        "BRAND_RECALL_UNAIDED",
        "BRAND_AWARENESS_AIDED"
      ]
    },
    {
      "key": "FAMILIARITY_USAGE",
      "purpose": "Measure familiarity, competitive trial and repertoire, usage intensity, platform behavior, and Fortnite lifecycle status, supporting the funnel, competitive, behavioral, and segment-comparison objectives.",
      "question_keys": [
        "BRAND_FAMILIARITY",
        "BRAND_TRIAL",
        "USAGE_PROFILE",
        "FORTNITE_STATUS"
      ]
    },
    {
      "key": "PERCEPTION_EQUITY",
      "purpose": "Measure consideration, comparative brand equity, attributes, current-player engagement, lapsed-player return barriers, and competitor conquest opportunities.",
      "question_keys": [
        "BRAND_ATTRIBUTES",
        "COMPETITOR_RATING_GRID",
        "BRAND_FUNNEL_CONSIDERATION",
        "CURRENT_FORTNITE_ENGAGEMENT",
        "LAPSED_FORTNITE_RETURN",
        "COMPETITOR_CONQUEST"
      ]
    },
    {
      "key": "EMOTIONAL_CONNECTION",
      "purpose": "Measure projective personality, emotional association, and aspiration gap to identify Fortnite's emotional and aspirational territory.",
      "question_keys": [
        "BRAND_PERSONALITY",
        "BRAND_EMOTION",
        "ASPIRATION_GAP"
      ]
    },
    {
      "key": "LOYALTY_ADVOCACY",
      "purpose": "Measure churn risk, advocacy, continuation, competitive choice, payer status, monetisation, spending barriers, and NPS before the final completion point.",
      "question_keys": [
        "CHURN_RISK",
        "RECOMMEND_AND_INVITE",
        "CONTINUE_AND_CHOOSE",
        "PAYER_STATUS",
        "PAYER_PURCHASE_VALUE",
        "NON_PAYER_SPENDING_BARRIERS",
        "NPS_SCORE"
      ]
    }
  ],
  "business_rules": [
    {
      "id": "BR1",
      "plain_english": "Ask BRAND_RECALL_UNAIDED before showing any aided brand list or naming the detailed tracked brands."
    },
    {
      "id": "BR2",
      "plain_english": "BRAND_AWARENESS_AIDED must include an exclusive None of these option. If None of these is selected with no other option, terminate immediately as non-aware and ineligible."
    },
    {
      "id": "BR3",
      "plain_english": "If at least one tracked brand or title is selected in BRAND_AWARENESS_AIDED, classify the respondent as brand_aware and continue."
    },
    {
      "id": "BR4",
      "plain_english": "Use BRAND_TRIAL to measure the competitive repertoire and carry only selected trial brands, in the same option order, into COMPETITOR_RATING_GRID."
    },
    {
      "id": "BR5",
      "plain_english": "Use USAGE_PROFILE to capture bundled frequency, recency, session duration, platform mix, multiplayer behavior, and Fortnite share-of-play indicators without adding separate questions beyond the 22-question budget."
    },
    {
      "id": "BR6",
      "plain_english": "Use FORTNITE_STATUS to route current players to current engagement, lapsed players to stopping and return diagnostics, competitor-only players to conquest diagnostics, and other aware respondents past lifecycle-specific modules."
    },
    {
      "id": "BR7",
      "plain_english": "Use recency anchoring consistently for play, stopping, switching, returning, and purchasing measures across all waves."
    },
    {
      "id": "BR8",
      "plain_english": "Use stable wording and scales for core tracking KPIs. Any wave-specific campaign, collaboration, seasonal, creator, esports, or competitor content must be incorporated without changing the core order or question budget."
    },
    {
      "id": "BR9",
      "plain_english": "Use PAYER_STATUS to route purchasers to purchase behavior and value measures and non-payers to spending barriers and value measures."
    },
    {
      "id": "BR10",
      "plain_english": "Use projective personality, aspiration gap, and a price-anchor approach within the declared questions; the price anchor must not create price cells or experimental assignment."
    },
    {
      "id": "BR11",
      "plain_english": "Apply external quality controls for attention, speed, straight-lining, open-end quality, duplicate records, and implausible behavior. Failed quality cases are quality terminates and must not be classified as non-aware screen-outs."
    },
    {
      "id": "BR12",
      "plain_english": "After NPS_SCORE, complete every respondent who has reached the final loyalty path. No mandatory questions or modules may follow NPS_SCORE."
    }
  ],
  "dynamic_lists": [
    {
      "id": "DL1",
      "source_question_key": "BRAND_TRIAL",
      "target_question_key": "COMPETITOR_RATING_GRID",
      "mode": "selected",
      "purpose": "Show only brands selected as used in BRAND_TRIAL, preserving the exact option labels and order for comparative quality, value, trust, and innovation ratings."
    }
  ],
  "branch_blocks": [
    {
      "id": "BB1",
      "source_question_key": "FORTNITE_STATUS",
      "selection_mode": "single",
      "blocks": [
        {
          "option_label": "Current Fortnite player",
          "member_question_keys": [
            "CURRENT_FORTNITE_ENGAGEMENT"
          ]
        },
        {
          "option_label": "Lapsed/former Fortnite player",
          "member_question_keys": [
            "LAPSED_FORTNITE_RETURN"
          ]
        },
        {
          "option_label": "Competitor player who has never played Fortnite",
          "member_question_keys": [
            "COMPETITOR_CONQUEST"
          ]
        },
        {
          "option_label": "Aware but not a current, lapsed, or competitor-only player",
          "member_question_keys": []
        }
      ],
      "rejoin_question_key": "BRAND_PERSONALITY"
    },
    {
      "id": "BB2",
      "source_question_key": "PAYER_STATUS",
      "selection_mode": "single",
      "blocks": [
        {
          "option_label": "Yes, made an in-app purchase",
          "member_question_keys": [
            "PAYER_PURCHASE_VALUE"
          ]
        },
        {
          "option_label": "No purchase in the recent period",
          "member_question_keys": [
            "NON_PAYER_SPENDING_BARRIERS"
          ]
        }
      ],
      "rejoin_question_key": "NPS_SCORE"
    }
  ],
  "termination_and_completion_policy": [
    {
      "condition": "BRAND_AWARENESS_AIDED selects None of these and no other aided-awareness option.",
      "outcome": "terminate"
    },
    {
      "condition": "A respondent fails an attention, speed, consistency, duplicate, open-end quality, or implausible-behavior validation.",
      "outcome": "terminate"
    },
    {
      "condition": "A brand-aware respondent does not qualify for a current-player, lapsed-player, or competitor-only module.",
      "outcome": "skip"
    },
    {
      "condition": "A respondent is not a current Fortnite player.",
      "outcome": "skip"
    },
    {
      "condition": "A respondent is not a payer in the defined recent purchase window.",
      "outcome": "skip"
    },
    {
      "condition": "A brand-aware respondent completes the applicable path through NPS_SCORE.",
      "outcome": "complete"
    }
  ],
  "question_generation_instructions": [
    "METHODOLOGY: Brand Tracking — Brand Equity Funnel. Use the mandated order: unaided recall, aided awareness with non-aware termination, familiarity and usage, perception and equity, emotional connection, then loyalty and advocacy.",
    "Generate exactly 22 respondent-facing questions using only the declared flow_keys. Do not add demographic, quota, or database-known targeting questions.",
    "Keep core wording, response scales, brand lists, and KPI definitions stable across waves. Use compact bundled questions where a flow_key explicitly covers multiple related metrics.",
    "BRAND_RECALL_UNAIDED must be open text and must precede BRAND_AWARENESS_AIDED. BRAND_AWARENESS_AIDED must be multi-select with an exclusive None of these option.",
    "Use BRAND_TRIAL as a multi-select source and carry its selected options, in identical labels and order, into the vertical-ranking COMPETITOR_RATING_GRID.",
    "Use recency anchoring for usage, recent play, stopping, switching, return, and purchase measures. Preserve the same time windows across waves.",
    "Use BRAND_ATTRIBUTES as a concise multi-select association measure covering fun, creativity, social connection, variety, competition, cultural relevance, trust, value, and distinctiveness.",
    "Use BRAND_PERSONALITY with the projective prompt 'If [Brand] were a person...' and BRAND_EMOTION with at least Excited, Trusted, Indifferent, and Disappointed.",
    "Use ASPIRATION_GAP to compare the current Fortnite or mobile-gaming experience with the experience respondents ideally want.",
    "Use a price-anchor technique within PAYER_PURCHASE_VALUE or NON_PAYER_SPENDING_BARRIERS without creating price cells or turning the study into a pricing experiment.",
    "Route current, lapsed, competitor-only, payer, and non-payer respondents through the declared branch blocks. Do not create duplicate per-question show-if logic.",
    "Use NPS_SCORE as a 0–10 number rating and place it as the final respondent-facing question and completion point.",
    "Ensure the data supports funnel conversion, competitive repertoire, share of play, usage intensity, brand differentiation, live-service engagement, switching, return, advocacy, monetisation, and segment-comparison analysis."
  ],
